/**
 * Static venue data loader
 * Falls back to generated JSON files when database is unavailable
 */

// Import generated JSON data
// These files are generated by scripts/buildSoftplayData.mjs
import venuesByTownData from '@/data/generated/venuesByTown.json'
import townsData from '@/data/generated/towns.json'

export interface StaticVenue {
  town: string
  townSlug: string
  name: string
  slug: string
  address: string
  postcode: string
  lat?: number | null
  lng?: number | null
  phone: string
  website: string
  mapsUrl: string
  googlePlaceId?: string
  category: string
  notes: string
  lastVerified: string
  description?: string
  openingHoursText?: string
  // Google rating
  rating?: number | null
  reviewCount?: number | null
  // Facilities
  cafe?: boolean
  parking?: boolean
  parties?: boolean
  toddlerArea?: boolean
  babyArea?: boolean
  senFriendly?: boolean
  wheelchairAccess?: boolean
  freeWifi?: boolean
  hasOutdoorPlay?: boolean
  hasPartyRooms?: boolean
  hasSenSessions?: boolean
  hasRolePlay?: boolean
  hasMultiLevelPlay?: boolean
  // Pricing
  priceFrom?: number | null
  priceTo?: number | null
  pricingHint?: string
  mainImageUrl?: string | null
  featured?: boolean
}

export interface StaticTown {
  name: string
  slug: string
  venueCount: number
}

interface VenuesByTownEntry {
  town: string
  townSlug: string
  venues: StaticVenue[]
}

// Type the imported data
const venuesByTown = venuesByTownData as unknown as Record<string, VenuesByTownEntry>
const towns = townsData as unknown as StaticTown[]

/**
 * Get all towns from static data
 */
export function getStaticTowns(): StaticTown[] {
  return towns
}

/**
 * Get venues for a specific town from static data
 */
export function getStaticVenuesByTown(townSlug: string): StaticVenue[] {
  const townData = venuesByTown[townSlug]
  if (!townData) return []
  return townData.venues
}

/**
 * Get a specific venue by town slug and venue slug
 */
export function getStaticVenue(townSlug: string, venueSlug: string): StaticVenue | null {
  const venues = getStaticVenuesByTown(townSlug)
  return venues.find(v => v.slug === venueSlug) || null
}

/**
 * Get town info by slug
 */
export function getStaticTownBySlug(townSlug: string): { name: string; slug: string } | null {
  const townData = venuesByTown[townSlug]
  if (!townData) return null
  return {
    name: townData.town,
    slug: townData.townSlug
  }
}

/**
 * Check if static data exists for a town
 */
export function hasStaticDataForTown(townSlug: string): boolean {
  return townSlug in venuesByTown
}

/**
 * Get all town slugs from static data
 */
export function getAllStaticTownSlugs(): string[] {
  return Object.keys(venuesByTown)
}

/**
 * Total venue count across all towns in the static export. Used as the
 * display fallback wherever the live DB count is unavailable (e.g. during
 * SOFTPLAY_STATIC_BUILD builds), so those fallbacks track real data instead
 * of a hand-maintained number that silently goes stale.
 */
export function getStaticTotalVenueCount(): number {
  return towns.reduce((sum, town) => sum + town.venueCount, 0)
}
